(()=>{const tabs=[...document.querySelectorAll('.example-report-tabs [role=tab]')],panel=document.getElementById('client-report-viewer');panel.setAttribute('role','tabpanel');function label(){panel.setAttribute('aria-labelledby',tabs.find(t=>t.getAttribute('aria-selected')==='true').id)}tabs.forEach((t,i)=>{t.addEventListener('click',label);t.addEventListener('keydown',e=>{let n;if(e.key==='ArrowRight')n=(i+1)%tabs.length;if(e.key==='ArrowLeft')n=(i+tabs.length-1)%tabs.length;if(e.key==='Home')n=0;if(e.key==='End')n=tabs.length-1;if(n!==undefined){e.preventDefault();tabs[n].focus();tabs[n].click();}})});label()})();